#nullable enable
using JasperFx.Events;
using JasperFx.Events.Tags;
using Marten;
using Spend.Concurrency;
using Spend.Contracts;
using Wolverine.Http;

namespace Spend.Slices.Spend;

/// <summary>
/// THE SLICE THIS WHOLE FOLDER EXISTS FOR, and the one place the mechanism choice is a production decision
/// rather than a comparison.
///
/// The rule — <c>gwt-commit-2</c>, "spend in another project of the same department counts against the
/// budget" — is a rejection whose deciding facts live in streams this command does not write. The command
/// appends to ONE project stream; the commitment that would refuse it may sit in another. So
/// <c>FetchForWriting</c>, correct for every other decider in this kit, cannot see the conflict: two
/// writers on two project streams touch no common row and Postgres has nothing to detect.
///
/// THE CHOICE, STATED OUT LOUD BECAUSE NOTHING CHECKS IT: this endpoint uses DCB. Three other mechanisms
/// hold the same invariant and are built beside it in <c>Concurrency/CommitMechanisms.cs</c> — a guard row,
/// a reservation row behind a unique index, and an advisory lock — with the costs of each measured in
/// CrossAggregateRaceTests. DCB is chosen here because Marten maintains the version row itself, so no
/// slice has to remember to write it (the guard-row arm needed SetBudget to pre-create its row, and
/// forgetting that made the guard silently useless). It is additive: the event still goes to the project's
/// own stream, with the tag attached.
///
/// The alternatives are not hypothetical and the trade is real — an advisory lock would let no attempt be
/// wasted, since its loser is refused by the budget rule rather than by a conflict and never retries.
/// DCB is preferred here for maintenance, not for throughput.
/// </summary>
public static class CommitSpendEndpoint
{
    public const string Route = "/projects/{projectId}/commit";

    /// <summary>The rule name IS the outcome, and it is the ProblemDetails Title — the same shape
    /// Wolverine.HTTP produces for a FluentValidation failure, so <c>then="error: DepartmentBudgetExceeded"</c>
    /// asserts identically whether a rule is caught at the periphery or in the decider.</summary>
    public const string BudgetExceeded = "DepartmentBudgetExceeded";

    [WolverinePost(Route)]
    public static async Task<IResult> Commit(Guid projectId, CommitSpend command, IDocumentSession session)
    {
        // THE BUDGET comes from the Department stream, which this command does not write. FetchLatest, on
        // IDocumentSession.Events rather than the query session — reading another stream is a read, and it
        // adds no check at save time. That is fine: the budget is not the contended thing, the TOTAL is.
        var department = await session.Events.FetchLatest<SetBudgetState>(command.DepartmentId);
        var budget = department?.Budget ?? 0m;

        // THE CONTENDED TOTAL, folded across every project stream carrying this department's tag, with the
        // tag's version captured. At SaveChangesAsync Marten re-checks that version against
        // mt_dcb_tag_version, so a second writer that read the same state and appends to a DIFFERENT
        // project stream still collides — on the tag row rather than on a stream.
        var query = new EventTagQuery().Or<DepartmentTag>(new DepartmentTag(command.DepartmentId));
        var boundary = await session.Events.FetchForWritingByTags<DepartmentBoundary>(query);
        var committed = boundary.Aggregate?.Committed ?? 0m;

        if (committed + command.Amount > budget)
            return Results.Problem(title: BudgetExceeded, statusCode: StatusCodes.Status400BadRequest);

        var e = session.Events.BuildEvent(new SpendCommitted(projectId, command.DepartmentId, command.Amount));
        e.WithTag(new DepartmentTag(command.DepartmentId));
        session.Events.Append(projectId, e);

        try
        {
            // EXPLICIT, not AutoApplyTransactions: the conflict has to be catchable here to become a 409
            // rather than an unhandled 500. A lost race reaching the client as a 500 is the failure the
            // race tests exist to catch.
            await session.SaveChangesAsync();
        }
        catch (DcbConcurrencyException)
        {
            // A concurrent commit in this department won. The caller may retry, and on retry it re-reads
            // and is then correctly refused by the budget rule if there is no longer room.
            return Results.Problem(
                title: "ConcurrentCommitConflict", statusCode: StatusCodes.Status409Conflict);
        }

        return Results.NoContent();
    }
}
